(41564, 'Numbers 2:6', 'Numbers', 2, 6, 'د هغه د ډلې شمېر ۵۴۴۰۰ تنه دی.', 'د هغه د دلې شمېر ۵۴۴۰۰ تنه دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_2_6.mp3', 'https://drive.google.com/file/d/1mg8nbaWDTGs0WDHQ5x6z09i6UAOk_N1G/preview', 1761237841, 1761237841),
