(41566, 'Numbers 2:8', 'Numbers', 2, 8, 'د هغه د ډلې شمېر ۵۷۴۰۰ تنه دی.', 'د هغه د دلې شمېر ۵۷۴۰۰ تنه دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_2_8.mp3', 'https://drive.google.com/file/d/1N3QsY8z4gMYYkMrYu2dGoyh1QWJPGWF3/preview', 1761237841, 1761237841),
(41567, 'Numbers 2:9', 'Numbers', 2, 9, 'هغه ټول کسان چې د یهودا کمپ ته د هغوی د ډلو له مخې ورکړل شوي دي، د هغوی شمېر ۱۸۶۴۰۰ تنه دی. لومړی به دوی روان شي.', 'هغه تول کسان چې د یهودا کمپ ته د هغوی د دلو له مخې ورکرل شوی دی، د هغوی شمېر ۱۸۶۴۰۰ تنه دی. لومری به دوی روان شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_2_9.mp3', 'https://drive.google.com/file/d/1j6bePCfCiZ7L8WMRoybOtuVipRJb0tRB/preview', 1761237841, 1761237841),
