(41574, 'Numbers 2:16', 'Numbers', 2, 16, 'هغه ټول کسان چې د روبین کمپ ته د هغوی د ډلو له مخې ورکړل شوي دي، د هغوی شمېر ۱۵۱۴۵۰ تنه دی. دوهم به دوی روان شي.', 'هغه تول کسان چې د روبین کمپ ته د هغوی د دلو له مخې ورکرل شوی دی، د هغوی شمېر ۱۵۱۴۵۰ تنه دی. دوهم به دوی روان شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_2_16.mp3', 'https://drive.google.com/file/d/16yIsHACI0HcSLMdpvpzTmYNA1InvF59B/preview', 1761237841, 1761237841),
(41575, 'Numbers 2:17', 'Numbers', 2, 17, 'بیا د لومړنیو او اخرنیو دوو کمپونو په منځ کې دې لاویان روان شي او سپېڅلې خېمه دې یوسي. هر کمپ دې په هماغه ترتیب سره روان شي لکه څنګه چې هغوی خېمې ودروي. هر یو به په خپل ځای کې د خپل بیرغ لاندې وي.', 'بیا د لومرنیو او اخرنیو دوو کمپونو په منج کې دې لاویان روان شی او سپېچلې خېمه دې یوسی. هر کمپ دې په هماغه ترتیب سره روان شی لکه چنګه چې هغوی خېمې ودروی. هر یو به په خپل جای کې د خپل بیرغ لاندې وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_2_17.mp3', 'https://drive.google.com/file/d/1Rv3DAwv999f_ZvG9-ij892Lq3MGeLx38/preview', 1761237841, 1761237841),
(41576, 'Numbers 2:18', 'Numbers', 2, 18, 'د افرایم د کمپ ډلې به په لوېدیځ کې د خپل بیرغ لاندې وي. د افرایم د خلکو مشر د عمیهود زوی الیشمع دی.', 'د افرایم د کمپ دلې به په لوېدیج کې د خپل بیرغ لاندې وی. د افرایم د خلکو مشر د عمیهود زوی الیشمع دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_2_18.mp3', 'https://drive.google.com/file/d/1g47qs5JiHjDzXdWYIiF4mZiWknlaFGlb/preview', 1761237841, 1761237841),
